package tools; import java.nio.file.Files;import java.nio.file.Path; public final class CliSupport{private CliSupport(){}public static byte[] readBytes(String[] args)throws Exception{if(args.length==0)throw new IllegalArgumentException("path argument required");return Files.readAllBytes(Path.of(args[0]));}public static String readText(String[] args)throws Exception{return new String(readBytes(args),java.nio.charset.StandardCharsets.UTF_8);}public static void exitOnError(Exception e){System.err.println("error: "+e.getMessage());System.exit(2);}}
